/**
 * Seed opportunities + sources.
 *
 * Used as the data source for the public /jobs experience when there is no
 * database configured (see `db.ts#hasDb`). The copy here is intentionally
 * high-quality so the page looks like a real product out of the box.
 *
 * IDs/slugs are stable strings — they only need to be unique within this
 * in-memory dataset (real UUIDs are generated by Postgres in DB mode).
 */

import type { Opportunity, OpportunitySource } from "./types";

function daysFromNow(n: number): string {
    const d = new Date();
    d.setDate(d.getDate() + n);
    return d.toISOString();
}

function daysAgo(n: number): string {
    return daysFromNow(-n);
}

type SeedOpp = Omit<
    Opportunity,
    "viewCount" | "applyCount" | "saveCount" | "createdAt" | "updatedAt" | "publishedAt"
> & { ageDays: number };

